import{_ as a,C as o,o as i,c as n,E as r,a2 as s}from"./chunks/framework.Cm6XCzck.js";const g=JSON.parse('{"title":"Evidence: approval scope and operation identity","description":"","frontmatter":{"title":"Evidence: approval scope and operation identity","outline":"deep"},"headers":[],"relativePath":"en/research/evidence/2026-09-04-approval-operation-identity.md","filePath":"en/research/evidence/2026-09-04-approval-operation-identity.md","lastUpdated":1788532182000}'),d={name:"en/research/evidence/2026-09-04-approval-operation-identity.md"};function c(l,e,p,h,u,m){const t=o("ArticleTableScroll");return i(),n("div",null,[r(t,{language:"en"}),e[0]||(e[0]=s('<h1 id="companion-evidence-approval-scope-and-operation-identity" tabindex="-1">Companion evidence: approval scope and operation identity <a class="header-anchor" href="#companion-evidence-approval-scope-and-operation-identity" aria-label="Permalink to &quot;Companion evidence: approval scope and operation identity&quot;">​</a></h1><p>For the <a href="/joinwell52/en/engineering/2026-09-04-approval-operation-identity">English article</a>. <a href="/joinwell52/zh/research/evidence/2026-09-04-approval-operation-identity">中文说明</a>. Nature: <strong>public companion records of controlled experiments; neither a fix receipt nor independent QA.</strong></p><h2 id="reading-the-evidence" tabindex="-1">Reading the evidence <a class="header-anchor" href="#reading-the-evidence" aria-label="Permalink to &quot;Reading the evidence&quot;">​</a></h2><p>This package is a de-identified extract of recorded research, not a substitute for rerunning it. All observations use CodeFlowMu commit <code>fdadbed489129455437f25202a03bae6e0c2e822</code>, dated September 4, 2026.</p><table tabindex="0"><thead><tr><th>Article claim</th><th>Record location</th><th>Check and expected observation</th><th>Scope</th></tr></thead><tbody><tr><td>Existing protections pass twice</td><td><code>observations.json → baseline_tests</code></td><td>31 tests/passes per run; no failures/skips; exit 0</td><td>Four selected files, not full acceptance</td></tr><tr><td>Changed branch consumes approval</td><td><code>approval_matrix</code>, different-target</td><td>ALLOW and consumed twice; replay reports APPROVAL_ALREADY_CONSUMED</td><td>Actual Native gate; no command execution</td></tr><tr><td>Registered wake session fails to match</td><td><code>approval_matrix</code>, delivered-resume</td><td>REQUIRE_APPROVAL twice; authorization available</td><td>Controlled session input, not complete successor admission</td></tr><tr><td>Four Git mutations keep the digests</td><td><code>field_comparisons</code>, branch/remote/force/delete</td><td>Equal fingerprints and digests, empty request differences, twice each</td><td>Digest boundary, not consumption/execution of all variants</td></tr><tr><td>Nested Session changes the digest</td><td><code>field_comparisons</code>, new-session</td><td>Equal fingerprint, unequal digest; removing nested Session in memory restores equality</td><td>Causal isolation, not a product patch</td></tr><tr><td>Codex resolution accepts a changed branch</td><td><code>codex_resolution</code>, changed-branch</td><td>allow=true and consumed twice; same-command is the control</td><td>Real local function, not a live app-server test</td></tr><tr><td>Identical task text does not replace a dependency</td><td><code>lineage_controls</code></td><td>Six cases, two repetitions; actual matches expected</td><td>FCoP gate branches, not complete graph recovery</td></tr></tbody></table><h2 id="sources-and-checks" tabindex="-1">Sources and checks <a class="header-anchor" href="#sources-and-checks" aria-label="Permalink to &quot;Sources and checks&quot;">​</a></h2><ul><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/approval-identity-20260904/evidence/observations.json" target="_blank" rel="noreferrer">Observations</a>: per-round results, including four retained assertion failures.</li><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/approval-identity-20260904/evidence/sources.json" target="_blank" rel="noreferrer">Source references</a>: Codex PR metadata and fixed CodeFlowMu file hashes.</li><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/approval-identity-20260904/evidence/manifest.json" target="_blank" rel="noreferrer">Integrity manifest</a>: hashes of articles, bilingual guides, and data.</li><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/approval-identity-20260904/evidence/check-evidence.mjs" target="_blank" rel="noreferrer">Reader/checker</a>: run <code>node check-evidence.mjs</code>.</li></ul><p>The checker validates file integrity, scenario sets, controls, and comparisons used by the article. Its expected message is <code>RECORDED EVIDENCE CONSISTENT; PRODUCT COUNTEREXAMPLES REMAIN</code>. That means the claims match the records, <strong>not that the product passes</strong>.</p><p>The complete E1 research probe exited 1 because two expectation violations each occurred twice. This package preserves that fact. The causal collector&#39;s exit 0 means collection completed. The 31 regression tests, 22 approval inputs, 14 field comparisons, four resolution observations, and 12 lineage observations are different sets, not a reliability percentage.</p><h2 id="de-identification" tabindex="-1">De-identification <a class="header-anchor" href="#de-identification" aria-label="Permalink to &quot;De-identification&quot;">​</a></h2><p>Projects, tasks, and commands were already isolated synthetic fixtures, not customer incidents. Export replaces local fixture paths with stable <code>&lt;SYNTHETIC_FIXTURE_...&gt;</code> labels and omits process numbers. Order, repetitions, timestamps, input semantics, outcomes, failures, and original digests remain. Labels are not executable paths.</p><p><strong>The operation digests are original observed values. They cannot be recomputed from path-redacted JSON.</strong> The checker verifies recorded equality/inequality relationships and references to original file hashes. Reproducing product behavior requires the original research scripts, fixed source, and dependencies. This reader is not the product experiment runner and does not establish causation or real network execution by itself.</p><p>Failures were not removed. Equal force/delete digests were not promoted to claims of Git execution. Research-tool API mistakes, a spec/TAP counter correction, and incomplete debugging rounds are excluded from the counted dataset; limitations are retained in <a href="/joinwell52/en/engineering/2026-09-04-approval-operation-identity">section 6 of the article</a> and the original research record. This package contains only completed rounds cited by the article.</p><p>No real push, cloud-model call, live takeover, power-loss recovery, or independent QA was performed. Both article languages and evidence guides use the same machine-readable dataset.</p><h2 id="offline-check" tabindex="-1">Offline check <a class="header-anchor" href="#offline-check" aria-label="Permalink to &quot;Offline check&quot;">​</a></h2><p><a href="https://joinwell52-ai.github.io/joinwell52/assets/approval-identity-20260904/approval-identity-evidence.zip" target="_blank" rel="noreferrer">Download the complete companion ZIP</a>, extract it, enter the evidence directory and run <code>node check-evidence.mjs</code>. Keep the complete directory structure; downloading the script alone is insufficient for the integrity check.</p>',16))])}const v=a(d,[["render",c]]);export{g as __pageData,v as default};
